CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS render_workers(id uuid PRIMARY KEY,name text NOT NULL,node_version text NOT NULL,git_sha text,status text NOT NULL,last_seen timestamptz NOT NULL DEFAULT now(),machine jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS render_jobs(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),payload jsonb NOT NULL,git_sha char(40) NOT NULL,status text NOT NULL CHECK(status IN ('QUEUED','CLAIMED','PREPARING','RENDERING','UPLOADING','COMPLETED','CANCEL_REQUESTED','CANCELLED','FAILED')),priority integer NOT NULL DEFAULT 0,scheduled_at timestamptz NOT NULL DEFAULT now(),worker_id uuid REFERENCES render_workers(id),lease_token uuid,lease_until timestamptz,progress double precision NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 1),stage text NOT NULL DEFAULT 'queued',error text,artifacts jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_job_per_worker ON render_jobs(worker_id) WHERE status IN ('CLAIMED','PREPARING','RENDERING','UPLOADING','CANCEL_REQUESTED');
CREATE INDEX IF NOT EXISTS pending_jobs ON render_jobs(priority DESC,created_at) WHERE status='QUEUED';
CREATE TABLE IF NOT EXISTS render_events(id bigserial PRIMARY KEY,render_id uuid NOT NULL REFERENCES render_jobs(id),status text NOT NULL,stage text NOT NULL,progress double precision NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assets(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),sha256 char(64) NOT NULL,pathname text NOT NULL UNIQUE,size bigint NOT NULL CHECK(size>0),content_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS deduplicated_assets ON assets(project_id,sha256);
CREATE TABLE IF NOT EXISTS queue_outbox(render_id uuid PRIMARY KEY REFERENCES render_jobs(id),sent_at timestamptz,attempts integer NOT NULL DEFAULT 0);
